eight:16px;accent-color:var(--rl-lp);cursor:pointer;flex-shrink:0}.rl-hint-text{font-size:11px;color:var(--rl-ls);line-height:1.4}.rl-actions-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding-top:4px}.rl-lang-chip{appearance:none;cursor:pointer;border:1px solid var(--rl-b);background:var(--rl-l3);color:var(--rl-ls);font-size:11px;font-weight:700;padding:2px 7px;border-radius:6px;display:inline-flex;align-items:center;transition:all .15s;margin:0 4px}.rl-lang-chip:hover{border-color:var(--rl-lp);color:var(--rl-lp)}.rl-lang-chip-active{color:var(--rl-lp);border-color:var(--rl-lp);background:var(--rl-l2)}.rl-action-btn{appearance:none;background:0 0;border:1px solid transparent;border-radius:4px;color:var(--rl-ls);cursor:pointer;font-size:11px;padding:2px 5px;display:inline-flex;align-items:center;transition:all .15s}.rl-action-btn:hover{color:var(--rl-lp);border-color:var(--rl-b);background:var(--rl-l3)}.rl-action-btn-active{color:var(--rl-lp);background:var(--rl-l2);border-color:var(--rl-b)}.rl-turn-translation{margin:8px 0;padding:10px 12px;border:1px solid var(--rl-b);background:var(--rl-l2);border-radius:8px;font-size:13px;line-height:1.5}.rl-trans-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;border-bottom:1px solid var(--rl-b);padding-bottom:4px}.rl-trans-title{font-size:11px;font-weight:600;color:var(--rl-ls);text-transform:uppercase;letter-spacing:0.5px}.rl-trans-tools{display:flex;gap:4px}.rl-trans-btn{appearance:none;background:var(--rl-l3);border:1px solid var(--rl-b);color:var(--rl-ls);cursor:pointer;padding:2px 7px;border-radius:4px;font-size:11px}.rl-trans-btn:hover{background:var(--rl-l1);color:var(--rl-lp)}.rl-trans-body{color:var(--rl-lp);white-space:pre-wrap;word-break:break-word;user-select:text}.rl-export-md-btn{appearance:none;border:1px solid var(--rl-b);height:32px;color:var(--rl-lp);cursor:pointer;background:transparent;border-radius:18px;justify-content:center;align-items:center;gap:4px;padding:6px 12px;font-size:13px;font-weight:500;display:inline-flex;white-space:nowrap;margin-left:6px;transition:all .15s ease}.rl-export-md-btn:hover{background:var(--dsw-alias-interactive-bg-hover)}.rl-inspector-hover{position:absolute;pointer-events:none;border:2px solid var(--rl-sb);border-radius:4px;background:color-mix(in srgb,var(--rl-sb) 12%,transparent);box-shadow:0 0 10px color-mix(in srgb,var(--rl-sb) 30%,transparent);z-index:99998;transition:all .06s ease;display:none}.rl-inspector-badge{position:absolute;bottom:calc(100% + 4px);left:0;background:var(--rl-sb);color:var(--dsw-alias-label-primary-inverted);font-size:10px;font-weight:600;padding:2px 6px;border-radius:4px;white-space:nowrap;box-shadow:var(--dsw-elevation-soft);pointer-events:none}.rl-inspector-pill{position:fixed;bottom:18px;right:18px;background:var(--rl-l2);color:var(--rl-lp);border:1px solid var(--dsw-alias-border-l1);border-radius:20px;padding:6px 12px;box-shadow:var(--dsw-shadow-lv3);display:none;align-items:center;gap:8px;font-size:12px;z-index:99990;user-select:none}.rl-inspector-pill-active{border-color:var(--rl-sb);box-shadow:0 0 12px color-mix(in srgb,var(--rl-sb) 35%,transparent)}'].join('')\nconst STYLE_ID = 'dsh-russian-lang-styles'\nif (typeof document !== 'undefined' && (document.getElementById && !document.getElementById(STYLE_ID))){const tag = document.createElement('style')\ntag.id = STYLE_ID\nif (tag.dataset){tag.dataset.dshPlugin = 'dsh-russian-lang'\ntag.dataset.plugin = '@goodandready/dsh-russian-lang'\ntag.dataset.pluginCss = 'rl-card'}\ntag.textContent = RL_CSS\ndocument.head.appendChild(tag)}\nmodule.exports = {apply,inject:['slots','locale','configForms'],resolveTypography,SettingsCard,QuickLangSwitch,ExportMarkdownButton,FallbackChevron,domMultiplexer,ui:{getOrCreateInspectorHost,createQuickSwitchElement,updateQuickSwitchElement,filterPlugins,getPluginStatusBadge,getDiagnosticsBadges,getSupportedEngines,buildProposalPayload,createInspectorPillElement}}\nreturn module.exports},})"
    },
    {
      "path": "lib/commands.js",
      "content": "/**\n * Русские слэш-команды для DeepSeek Harness (@deepseek-ai/dsh-commands).\n * Реализация issue #548: поддержка официального API commands.execute(agent, line, attachments, signal).\n */\n\nexport const SLASH_ALIASES = [\n  { name: 'цель', target: 'goal', desc: 'Автономный режим целей и задач', hint: '<цель>' },\n  { name: 'план', target: 'plan', desc: 'Планирование и декомпозиция задач', hint: '<план>' },\n  { name: 'память', target: 'memory', desc: 'Управление долговременной памятью', hint: '<действие>' },\n  { name: 'контекст', target: 'context', desc: 'Анализ и сжатие контекста' },\n  { name: 'сжать', target: 'compact', desc: 'Сжатие контекста истории диалога' },\n  { name: 'очистить', target: 'clear', desc: 'Очистка истории диалога' },\n  { name: 'команда', target: 'teamwork', desc: 'Командное взаимодействие субагентов' },\n  { name: 'справка', target: 'help', desc: 'Справка по доступным командам' },\n  { name: 'помощь', target: 'help', desc: 'Справка по доступным командам' },\n  { name: 'задача', target: 'task', desc: 'Управление текущей задачей', hint: '<описание>' },\n  { name: 'экспорт', target: 'export', desc: 'Экспорт диалога в файл', hint: '<формат>' },\n  { name: 'отзыв', target: 'feedback', desc: 'Обратная связь' },\n  { name: 'разрешение', target: 'permission', desc: 'Настройки песочницы и подтверждений', hint: '<preset>' },\n  { name: 'разрешения', target: 'permission', desc: 'Настройки песочницы и подтверждений', hint: '<preset>' },\n  { name: 'сессия', target: 'session', desc: 'Управление текущей сессией' },\n  { name: 'модель', target: 'model', desc: 'Выбор модели LLM' }\n]\n\nexport function registerSlashAliases(ctx, readSettings) {\n  const commands = ctx?.commands || ctx?.['commands'] || (typeof ctx?.get === 'function' ? ctx.get('commands') : null)\n  if (!commands || typeof commands.register !== 'function') return () => {}\n\n  const disposers = []\n  for (const alias of SLASH_ALIASES) {\n    try {\n      const disp = commands.register({\n        name: alias.name,\n        description: alias.desc,\n        input: alias.hint ? { hint: alias.hint } : undefined,\n        handler: async (invocation) => {\n          if (typeof readSettings === 'function') {\n            const settings = readSettings()\n            if (settings && settings.slashAliases === false) {\n              return {\n                kind: 'error',\n                text: 'Русские слэш-команды отключены в настройках dsh-russian-lang.'\n              }\n            }\n          }\n\n          const raw = typeof invocation?.rawInput === 'string'\n            ? invocation.rawInput\n            : (typeof invocation?.args === 'string' ? invocation.args : '')\n          const line = '/' + alias.target + (raw ? (raw.startsWith(' ') ? raw : ' ' + raw) : '')\n          const attachments = Array.isArray(invocation?.attachments) ? invocation.attachments : []\n          const signal = invocation?.signal || (typeof AbortController !== 'undefined' ? new AbortController().signal : undefined)\n          const agent = invocation?.agent || (invocation?.session?.agent) || (invocation?.session) || {}\n\n          // 1. DSH official execution API: execute(agent, line, attachments, signal)\n          if (typeof commands.execute === 'function') {\n            let execRes\n            // Support both official 4-arg DSH API and 2-arg mock execute(target, invocation)\n            if (commands.execute.length === 2) {\n              execRes = await commands.execute(alias.target, invocation)\n            } else {\n              try {\n                execRes = await commands.execute(agent, line, attachments, signal)\n              } catch (e) {\n                try {\n                  execRes = await commands.execute(alias.target, invocation)\n                } catch (_) {\n                  throw e\n                }\n              }\n            }\n            if (execRes && typeof execRes === 'object') {\n              if (execRes.result && typeof execRes.result === 'object') return execRes.result\n              return execRes\n            }\n            return { kind: 'success', text: String(execRes || '') }\n          }\n\n          // 2. Direct lookup via commands.view(agent)\n          if (typeof commands.view === 'function') {\n            let targetCmd = null\n            try {\n              const view = commands.view(agent)\n              targetCmd = view?.get ? view.get(alias.target) : null\n            } catch {\n              /* ignore view lookup error and try fallbacks */\n            }\n            if (targetCmd?.definition?.handler) {\n              return await targetCmd.definition.handler({\n                agent,\n                rawInput: raw,\n                attachments,\n                signal\n              })\n            }\n          }\n\n          // 3. session.executeCommand\n          const session = invocation?.session || invocation?.agent?.session\n          if (typeof session?.executeCommand === 'function') {\n            return await session.executeCommand(alias.target, raw)\n          }\n\n          // 4. commands.registered array lookup\n          if (commands.registered && typeof commands.registered.find === 'function') {\n            const targetDef = commands.registered.find((c) => c.name === alias.target)\n            if (targetDef && typeof targetDef.handler === 'function') {\n              return await targetDef.handler(invocation)\n            }\n          }\n\n          // 5. commands.get(name) lookup\n          if (typeof commands.get === 'function') {\n            const targetDef = commands.get(alias.target)\n            if (targetDef && typeof targetDef.handler === 'function') {\n              return await targetDef.handler(invocation)\n            }\n          }\n\n          return {\n            kind: 'error',\n            text: `Команда /${alias.target} недоступна в текущем окружении.`\n          }\n        }\n      })\n      if (typeof disp === 'function') disposers.push(disp)\n    } catch (_) { /* bestEffort */ }\n  }\n\n  return () => {\n    for (const d of disposers) {\n      try { d() } catch {\n        /* bestEffort */\n      }\n    }\n  }\n}\n"
    },
