      "path": "lib/plugin-updater.js",
      "content": "import { isTrustedLocalRequest } from './translator.js'\nimport { spawn } from 'node:child_process'\nimport { existsSync, readFileSync } from 'node:fs'\nimport { readFile } from 'node:fs/promises'\nimport { dshHomePath } from '@deepseek-ai/dsh-home-paths'\nimport { basename, dirname, isAbsolute, resolve } from 'node:path'\nimport { fileURLToPath } from 'node:url'\n\n/**\n * Host-side one-click updater for @goodandready/dsh-russian-lang.\n * Implements the unified DSH plugin updater standard.\n */\n\nconst UPDATE_HEADER = 'x-dsh-plugin-update'\nconst UPDATE_TIMEOUT_MS = 10 * 60_000\nconst VERSION_CACHE_MS = 5 * 60_000\nlet latestCache = undefined\n\nfunction header(request, name) {\n  const value = request.headers?.[name]\n  return Array.isArray(value) ? value[0] : value\n}\n\nexport function isIPv4Loopback(v4) {\n  if (typeof v4 !== 'string') return false\n  const parts = v4.split('.')\n  return (\n    parts.length === 4 &&\n    parts[0] === '127' &&\n    parts.every((part) => /^\\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255)\n  )\n}\n\nexport function isLoopbackAddress(address) {\n  if (address === undefined || typeof address !== 'string') return false\n  const normalized = address.toLowerCase().replace(/^\\[|\\]$/g, '')\n  if (normalized === 'localhost' || normalized === 'localhost.' || normalized === '::1') return true\n  if (normalized.startsWith('::ffff:')) {\n    const rest = normalized.slice('::ffff:'.length)\n    return isIPv4Loopback(rest)\n  }\n  return isIPv4Loopback(normalized)\n}\n\nexport function isLoopbackHostname(hostname) {\n  if (typeof hostname !== 'string') return false\n  const normalized = hostname.toLowerCase().replace(/^\\[|\\]$/g, '')\n  if (normalized === 'localhost' || normalized === 'localhost.' || normalized === '::1') return true\n  return isIPv4Loopback(normalized)\n}\n\nexport function isLoopback(value) {\n  return isLoopbackAddress(value)\n}\n\nexport function isTrustedUpdateRequest(request) {\n  if (header(request, UPDATE_HEADER) !== '1') return false\n  if (!isLoopbackAddress(request?.socket?.remoteAddress)) return false\n\n  const host = header(request, 'host')\n  if (typeof host !== 'string' || host === '') return false\n  let hostUrl\n  try {\n    hostUrl = new URL('http://' + host)\n  } catch {\n    return false\n  }\n  if (!isLoopbackHostname(hostUrl.hostname)) return false\n\n  const site = header(request, 'sec-fetch-site')\n  const origin = header(request, 'origin')\n\n  if (site === 'cross-site') {\n    if (origin === undefined) return false\n  }\n\n  if (origin === undefined || origin === 'null') return true\n\n  try {\n    const url = new URL(origin)\n    if (\n      url.protocol === 'file:' ||\n      url.protocol === 'vscode-file:' ||\n      url.protocol === 'dsh:' ||\n      url.protocol === 'app:'\n    ) {\n      return true\n    }\n    if (url.protocol !== 'http:' && url.protocol !== 'https:') {\n      return false\n    }\n    if (url.host === hostUrl.host) return true\n\n    if (isLoopbackHostname(url.hostname) && isLoopbackHostname(hostUrl.hostname)) {\n      const urlPort = url.port || (url.protocol === 'https:' ? '443' : '80')\n      const hostPort = hostUrl.port || '80'\n      if (urlPort === hostPort) return true\n    }\n    return false\n  } catch {\n    return false\n  }\n}\n\nfunction validProfileName(value) {\n  return (\n    typeof value === 'string' &&\n    value !== '' &&\n    value !== '.' &&\n    value !== '..' &&\n    !value.includes('/') &&\n    !value.includes('\\\\') &&\n    !/[\\0-\\x1f\\x7f]/.test(value)\n  )\n}\n\nfunction profileNameFromArgv(argv) {\n  for (let index = 2; index < argv.length; index += 1) {\n    if (argv[index] === '--profile') return argv[index + 1]\n    if (argv[index]?.startsWith('--profile=')) return argv[index].slice('--profile='.length)\n  }\n  return argv[2] === 'web' ? 'web' : undefined\n}\n\nfunction findDshCliEntry() {\n  const value = process.argv[1]\n  if (value === undefined || value === '')